    },
    {
      "id": 3,
      "claim": "Insured individuals usually have most of the CT cost covered by their health plan.",
      "evidence": "Most private and public insurance plans include diagnostic imaging benefits with copays or deductibles that are far lower than the full charge.",
      "weight": 0.15,
      "depends_on": []
